//   * 模块级导出 `apply` / `inject`；factory 顶部先把 `exports.apply` 占位，
//     末尾再赋真正实现。
//
// 功能（按用户三条要求）：
//   1) 正确导出 apply，不再让 shell 崩；
//   2) 设置项注册进 dream-skin 的 `settings.dreamSkin.item` 插槽
//      （即 设置 → Theme / 外观 页），不另开面板；
//   3) 数值输入框 + 1px 步进（非滑块），并带 −10/−1/+1/+10 微调。
//
// 位移按"当前壁纸内容哈希"存 localStorage：每张图各自记忆。
// 生效方式：background-position: calc(50% + var(--wp-x)) calc(50% + var(--wp-y))，
// 变量挂在 :root；仅在该层内联含 background-image 时生效，默认观感不变。

window.__ModuleLoader__.load({
	id: 'dsh-wallpaper-position',
	factory: (require) => {
		var module = { exports: {} };
		var exports = module.exports;
		Object.defineProperty(exports, Symbol.toStringTag, { value: 'Module' });

		// ── 平台 seed 防御式解析（缺失则降级为哑模块）───────────────────────
		const seedProbe = { lastError: null };
		const requireSeed = (name) => {
			try { return require(name); } catch (err) { seedProbe.lastError = err; return null; }
		};
		const _react = requireSeed('react');
		if (_react === null) {
			try {
				console.warn('[wallpaper-position] 宿主模块不可用，本会话内插件已禁用：',
					seedProbe.lastError && seedProbe.lastError.message);
			} catch (e) {}
			exports.apply = () => {};
			exports.inject = [];
			return module.exports;
		}

		const POS_KEY = 'dsh-wallpaper-position:map';
		const IMG_KEY = 'dsh-dream-skin:wallpaper';            // 图片壁纸（data URL）
		const URL_KEY = 'dsh-dream-skin:wallpaper-url';        // URL 壁纸
		const GRADIENT_KEY = 'dsh-dream-skin:wallpaper-gradient'; // 渐变壁纸
		const KIND_KEY = 'dsh-dream-skin:wallpaper-kind';      // 'image' | 'url' | 'gradient'
		const VAR_X = '--wp-x';
		const VAR_Y = '--wp-y';
		const STYLE_ID = 'dsh-wallpaper-position-style';
		const LIMIT = 5000;                            // 位移上限（px）

		// ── 每张图各自的位移 ────────────────────────────────────────────────
		function readMap() {
			try {
				const raw = localStorage.getItem(POS_KEY);
				const o = raw ? JSON.parse(raw) : null;
				return o && typeof o === 'object' ? o : {};
			} catch (e) { return {}; }
		}
		function writeMap(m) {
			try { localStorage.setItem(POS_KEY, JSON.stringify(m)); } catch (e) {}
		}
		function clampNum(v) {
			const n = Math.round(Number(v) || 0);
			return Math.max(-LIMIT, Math.min(LIMIT, n));
		}
		// 已挂载的数值输入框。换壁纸后要把面板里的数字同步成「新壁纸的记忆值」——
		// 旧版只在挂载时读一次，换图后显示的还是上一张图的数值（实际位移已经作用到新图），
		// 会误导用户。这里登记起来，由轮询统一回写。
		const liveInputs = [];
		let lastId = null;   // 上一次看到的壁纸指纹，用于检测「换壁纸」
		function refreshInputs() {
			for (let i = liveInputs.length - 1; i >= 0; i--) {
				const it = liveInputs[i];
				try {
					if (!document.body || !document.body.contains(it.input)) { liveInputs.splice(i, 1); continue }
					if (document.activeElement === it.input) continue;   // 别打断正在输入的用户
					const v = String(it.getVal());
					if (it.input.value !== v) it.input.value = v;
				} catch (e) { liveInputs.splice(i, 1) }
