			try { return localStorage.getItem(k); } catch (e) { return null; }
		}
		/**
		 * 当前壁纸：**按 dream-skin 的壁纸类型取对应的键**。
		 * dream-skin 把三种壁纸分别存在三个键里，并用 `wallpaper-kind` 标记类型：
		 *   image → dsh-dream-skin:wallpaper（data URL）
		 *   url   → dsh-dream-skin:wallpaper-url
		 *   gradient → dsh-dream-skin:wallpaper-gradient
