			const kind = readKey(KIND_KEY);
			if (kind === 'url') {
				const v = readKey(URL_KEY);
				return v ? { kind: 'url', value: v } : null;
			}
			if (kind === 'gradient') {
				const v = readKey(GRADIENT_KEY);
				return v ? { kind: 'gradient', value: v } : null;
			}
			const v = readKey(IMG_KEY);
			return v ? { kind: 'image', value: v } : null;
