export const name = "dsh-wallpaper-position";
/** 无 web 路由需求。 */
export const inject = [];

/**
 * ⚠️ 这个空 apply 不能省。
 * cordis 要求插件是函数，或"带 apply 方法的对象"；只导出 name/inject 的模块
 * 命名空间两者都不是，会被判为
 *   invalid plugin, expect function or object with an "apply" method, received object
 * 而 dsh 的插件加载器是 fail-fast：一个条目 apply 失败 → 整棵插件树 boot 失败
 * → dsh web 完全起不来。空实现也必须存在。
