      "content": "#!/usr/bin/env bash
# =============================================================================
# install.sh — 把 dsh-wallpaper-position 幂等安装进 dsh 的 web profile
#
#   1) 拷贝插件包到 $DSH_HOME/profiles/web/node_modules/dsh-wallpaper-position/；
#   2) 把 "dsh-wallpaper-position" 注册进 profile package.json 的 dsh.profile.bundles；
#   3) 静态自检。
#
# 关于「插件市场里显示已安装」：市场读的是 profile 的 dependencies（不是 bundles），
# 手装默认**不写** dependencies，避免 pnpm 下次 install 时把手装副本替换掉（离线会失败）。
# 要让市场识别就加 --market，或用官方方式装：
#   dsh plugin add github:ankhishtar2-lang/dsh-wallpaper-position
#
# 不重启任何服务。生效请自己执行：
#   systemctl --user restart dsh-web-profiled.service
# =============================================================================
set -uo pipefail

MARKET=0
for a in "$@"; do [ "$a" = "--market" ] && MARKET=1; done

PKG_NAME="dsh-wallpaper-position"
DEP_SPEC="${DSH_INSTALL_DEP_SPEC:-github:ankhishtar2-lang/dsh-wallpaper-position}"
SRC="${DSH_WP_SRC:-$(cd "$(dirname "${BASH_SOURCE[0]}")/.." && pwd)}"
DSH_HOME="${DSH_HOME:-$HOME/.dsh}"
PROFILE="${DSH_PROFILE_DIR:-$DSH_HOME/profiles/web}"
DEST="$PROFILE/node_modules/$PKG_NAME"
PKG="$PROFILE/package.json"
FAIL=0

ok()  { printf '   ✓ %s\n' "$*"; }
bad() { printf '   ✗ %s\n' "$*"; FAIL=1; }

printf '== 1) 拷贝插件文件 ==\n'
[ -d "$SRC/lib" ] || { bad "源目录不完整：$SRC"; exit 1; }
mkdir -p "$DEST/lib" || { bad "无法创建 $DEST"; exit 1; }
cp -f "$SRC/package.json" "$DEST/package.json"
cp -f "$SRC/cordis.patch.yml" "$DEST/cordis.patch.yml"
cp -f "$SRC/lib/index.js" "$DEST/lib/index.js"
cp -f "$SRC/lib/client.js" "$DEST/lib/client.js"
ok "已部署到 $DEST"

printf '== 2) 注册到 dsh.profile.bundles ==\n'
node - "$PKG" "$PKG_NAME" "$MARKET" "$DEP_SPEC" <<'NODE'
const fs = require('fs')
const [file, name, market, depSpec] = process.argv.slice(2)
const pkg = JSON.parse(fs.readFileSync(file, 'utf8'))
let changed = false
pkg.dsh = pkg.dsh || {}
pkg.dsh.profile = pkg.dsh.profile || {}
pkg.dsh.profile.bundles = pkg.dsh.profile.bundles || []
if (!pkg.dsh.profile.bundles.includes(name)) {
  pkg.dsh.profile.bundles.push(name)
  changed = true
  console.log('   ✓ 已加入 bundles')
} else {
  console.log('   ✓ bundles 中已存在（跳过）')
}
if (market === '1') {
  pkg.dependencies = pkg.dependencies || {}
  if (!pkg.dependencies[name]) {
    pkg.dependencies[name] = depSpec
    changed = true
    console.log('   ✓ 已加入 dependencies（市场会显示为已安装）: ' + depSpec)
  } else {
    console.log('   ✓ dependencies 中已存在: ' + pkg.dependencies[name])
  }
} else {
  console.log('   · 未写 dependencies（手装默认）；要让市场识别，加 --market 重新执行')
}
if (changed) fs.writeFileSync(file, JSON.stringify(pkg, null, 2) + '\n')
NODE
[ $? -eq 0 ] || bad "注册 bundles 失败"

printf '== 3) 静态自检 ==\n'
node --check "$DEST/lib/client.js" >/dev/null 2>&1 && ok "client.js 语法" || bad "client.js 语法"
node --input-type=module --check < "$DEST/lib/index.js" >/dev/null 2>&1 && ok "index.js 语法（ESM）" || bad "index.js 语法（ESM）"
grep -qE '^export function apply' "$DEST/lib/index.js" && ok "host 半有 apply 导出（fail-fast 红线）" || bad "host 半缺 apply 导出 —— 千万不要重启！"
if command -v dsh >/dev/null 2>&1; then
  dsh --profile web --dump-config >/dev/null 2>&1 && ok "dsh --profile web --dump-config 退出码 0" || bad "dump-config 失败，先别重启 dsh"
fi

printf '\n'
if [ "$FAIL" -eq 0 ]; then
  printf '全部通过。生效方式（由你执行）：\n  systemctl --user restart dsh-web-profiled.service\n'
else
  printf '存在失败项：先别重启 dsh。\n'
fi
exit "$FAIL"
"
